    public static final MaterialIcon WRONG_LOCATION = register("wrong_location", 0xEF78);
    /** Material icon glyph named {@code wysiwyg}. */
    public static final MaterialIcon WYSIWYG = register("wysiwyg", 0xF1C3);
    /** Material icon glyph named {@code x_circle}. */
    public static final MaterialIcon X_CIRCLE = register("x_circle", 0xE349);
    /** Material icon glyph named {@code y_circle}. */
    public static final MaterialIcon Y_CIRCLE = register("y_circle", 0xEEC5);
    /** Material icon glyph named {@code yakitori}. */
    public static final MaterialIcon YAKITORI = register("yakitori", 0xEF31);
    /** Material icon glyph named {@code yard}. */
    public static final MaterialIcon YARD = register("yard", 0xF089);
    /** Material icon glyph named {@code yoshoku}. */
    public static final MaterialIcon YOSHOKU = register("yoshoku", 0xF27F);
    /** Material icon glyph named {@code your_trips}. */
    public static final MaterialIcon YOUR_TRIPS = register("your_trips", 0xEB2B);
    /** Material icon glyph named {@code youtube_activity}. */
    public static final MaterialIcon YOUTUBE_ACTIVITY = register("youtube_activity", 0xF85A);
    /** Material icon glyph named {@code youtube_searched_for}. */
    public static final MaterialIcon YOUTUBE_SEARCHED_FOR = register("youtube_searched_for", 0xE8FA);
    /** Material icon glyph named {@code zone_person_alert}. */
    public static final MaterialIcon ZONE_PERSON_ALERT = register("zone_person_alert", 0xE781);
    /** Material icon glyph named {@code zone_person_idle}. */
    public static final MaterialIcon ZONE_PERSON_IDLE = register("zone_person_idle", 0xE77A);
    /** Material icon glyph named {@code zone_person_urgent}. */
    public static final MaterialIcon ZONE_PERSON_URGENT = register("zone_person_urgent", 0xE788);
    /** Material icon glyph named {@code zoom_in}. */
    public static final MaterialIcon ZOOM_IN = register("zoom_in", 0xE8FF);
    /** Material icon glyph named {@code zoom_in_map}. */
    public static final MaterialIcon ZOOM_IN_MAP = register("zoom_in_map", 0xEB2D);
    /** Material icon glyph named {@code zoom_out}. */
    public static final MaterialIcon ZOOM_OUT = register("zoom_out", 0xE900);
